def replace_html_formatter(func, formatter):
    @functools.wraps(func)
    def wrapped_f(*args, **kw):
        try:
            old, pd.core.format.HTMLFormatter = pd.core.format.HTMLFormatter, formatter
            return func(*args, **kw)
        finally:
            pd.core.format.HTMLFormatter = old
    return wrapped_f

