L2 = [('word1', 'page4'), ('word2', 'page2'), ('word3', 'page2'), ]

def func1():
    '''
    Time Complexity is O(n^2) 
    '''
    res = []
    for i in L1:
        for k in L2:
            if i[0] == k[0]:
                res.append(i)
                res.append(k)
    return list(set(res))

def func2():
    '''
    Time Complexity is O(n)
    '''
    d1 = {}
    for i in L1:
        if d1.has_key(i[0]):
            d1[i[0]].append(i[1])
        else:
            d1[i[0]] = [i[1]]
    d2 = {}
    for i in L2:
        if d2.has_key(i[0]):
            d2[i[0]].append(i[1])
        else:
            d2[i[0]] = [i[1]]
    d3 = {}
    for key in d1.keys():
        if d2.has_key(key):
            d3[key] = d2[key] + d1[key]

    return [(m,n) for m in d3.keys() for n in d3[m]]



